"""The persistent execute_code kernel (generated by Prometheus).

Runs cells in one namespace so imports and variables persist between
execute_code calls. The host writes a cell to <cells>/<n>.py and sends
"<n>" on stdin; the cell runs with stdin, stdout and stderr pointed at
<n>.in (empty), <n>.out and <n>.err, then one JSON line reports its exit
code on the real stdout.
"""
import json
import os
import sys
import traceback

CELLS = sys.argv[1]
NAMESPACE = {"__name__": "__main__", "__builtins__": __builtins__}
PROTOCOL = os.fdopen(os.dup(1), "w", encoding="utf-8")
COMMANDS = os.fdopen(os.dup(0), "r", encoding="utf-8")


def run(number):
    base = os.path.join(CELLS, number)
    with open(base + ".py", encoding="utf-8") as f:
        source = f.read()
    sys.stdout.flush()
    sys.stderr.flush()
    saved = [os.dup(fd) for fd in (0, 1, 2)]
    streams = [
        os.open(os.devnull, os.O_RDONLY),
        os.open(base + ".out", os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600),
        os.open(base + ".err", os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600),
    ]
    for fd, stream in enumerate(streams):
        os.dup2(stream, fd)
        os.close(stream)
    code = 0
    try:
        exec(compile(source, "<cell>", "exec"), NAMESPACE)
    except SystemExit as stop:
        code = stop.code if isinstance(stop.code, int) else (0 if stop.code is None else 1)
    except BaseException:
        traceback.print_exc()
        code = 1
    finally:
        sys.stdout.flush()
        sys.stderr.flush()
        for fd, old in enumerate(saved):
            os.dup2(old, fd)
            os.close(old)
    return code


for line in COMMANDS:
    number = line.strip()
    if not number:
        continue
    PROTOCOL.write(json.dumps({"cell": number, "exit_code": run(number)}) + "\n")
    PROTOCOL.flush()
